using System;
using System.Linq;
using System.Collections.Generic;
using EnusDE.Signaltechnik;

public static class FlankTests {
    static void Check(bool ok,string text){if(!ok)throw new Exception("FAIL: "+text);System.Console.WriteLine("PASS: "+text);}
    static TrackSection S(string id,double from=0,double to=25)=>new TrackSection{Segment=id,From=from,To=to};
    static NetworkInput Graph(double branch=60){var n=new NetworkInput();n.Nodes.AddRange(new[]{new PlanNode{Id="A"},new PlanNode{Id="W",Point=true,Common="common",Normal="normal"},new PlanNode{Id="B"},new PlanNode{Id="Q",Point=true,Common="qc",Normal="side"},new PlanNode{Id="C"},new PlanNode{Id="D"}});n.Edges.AddRange(new[]{new PlanEdge{Id="common",A="A",B="W",Length=100},new PlanEdge{Id="normal",A="W",B="B",Length=100},new PlanEdge{Id="side",A="W",B="Q",Length=branch},new PlanEdge{Id="qc",A="C",B="Q",Length=100},new PlanEdge{Id="qr",A="Q",B="D",Length=100}});return n;}
    static RouteDefinition Route(){var r=new RouteDefinition{Code="F",Entry="A",Exit="B",Sections=new List<TrackSection>{S("common",0,100),S("normal",0,100),S("side")},Approach=new List<TrackSection>{S("approach")},Switches=new List<RouteSwitch>{new RouteSwitch{Node="W",Thrown=false,ReleaseAt=100,Protection=new List<TrackSection>{S("common",75,100),S("normal"),S("side")}}},ViaSignals=new List<RouteViaSignal>(),Path=new List<DirectedRouteSection>{new DirectedRouteSection{Section=S("common",0,100)},new DirectedRouteSection{Section=S("normal",0,100)}}};return r;}
    sealed class World:IInterlockingWorld,IFlankOccupancyWorld {public bool Intrusion,Unknown;readonly Dictionary<string,bool> positions=new Dictionary<string,bool>{{"W",false},{"Q",true}};public bool PathValid(RouteDefinition r)=>true;public TrackOccupancy Occupancy(TrackSection s)=>TrackOccupancy.Clear;public TrackOccupancy FlankOccupancy(TrackSection s)=>Unknown?TrackOccupancy.Unknown:Intrusion?TrackOccupancy.Occupied:TrackOccupancy.Clear;public bool SwitchPosition(string id,out bool value)=>positions.TryGetValue(id,out value);public bool SetSwitch(string id,bool value){positions[id]=value;return true;}}
    public static void Run(){
        var legacy=Route();bool blocked=false;try{FlankProtection.RequireCalculated(legacy);}catch(InvalidOperationException){blocked=true;}Check(blocked,"legacy route with points must explicitly recalculate flank protection before UI can authorize a new request");
        var yard=Route();yard.Shunting=true;FlankProtection.Plan(yard,new NetworkInput(),new MarkerRecord[0]);yard.Validate();FlankProtection.RequireCalculated(yard);Check(yard.Flanks.Count==0&&yard.Switches.Count==1,"shunt routes retain their own point guards without requiring a flank installation or even a flank-network scan");
        var slow=Route();slow.Reduced=true;bool slowBlocked=false;try{FlankProtection.RequireCalculated(slow);}catch(InvalidOperationException){slowBlocked=true;}FlankProtection.Plan(slow,Graph(),new MarkerRecord[0]);RouteSignals.SplitProtection(slow);slow.Validate();Check(slowBlocked&&slow.Flanks.Count==1&&slow.Switches.Any(p=>p.FlankOf=="W"),"slow train routes keep the same calculated flank-protection requirement as normal train routes");
        var oldYard=slow.Clone();oldYard.Shunting=true;bool recalc=false;try{FlankProtection.RequireCalculated(oldYard);}catch(InvalidOperationException){recalc=true;}Check(recalc,"old shunt definitions with inherited flank locks request explicit recalculation instead of silently retaining obsolete protection");
        var route=Route();FlankProtection.Plan(route,Graph(),new MarkerRecord[0]);route.Validate();Check(route.Switches.Any(p=>p.Node=="Q"&&p.Thrown&&p.FlankOf=="W")&&route.Flanks.Count==1,"unused native branch selects a protective point position diverting away from the active route");Check(route.Flanks[0].Sections.Any(s=>s.Segment=="side"&&s.To==60)&&route.Flanks[0].Sections.Any(s=>s.Segment=="qc")&&!route.Flanks[0].MonitorOnly,"protective point has explicit reserved approach and point areas instead of only a short main-point guard");
        route=Route();var signal=new MarkerRecord{Id=Guid.NewGuid().ToString("N"),Name="RS",Kind=MarkerRecord.Shunt,FacingReverse=true,Anchor=new MarkerAnchor{Segment="side",Meters=30}};FlankProtection.Plan(route,Graph(),new[]{signal});route.Validate();Check(route.Flanks[0].Signals.Single().Id==signal.Id&&route.Flanks[0].Sections.Last().To==30&&route.Switches.Count==1,"suitable shunt signal facing the danger point becomes the flank stop resource and ends its watched approach");
        RouteSignals.SplitProtection(route);route.Validate();Check(route.Flanks[0].Sections.Where(s=>s.Segment=="side").Sum(s=>s.To-s.From)==30&&route.Flanks[0].Sections.All(s=>route.Sections.Any(p=>p.Key==s.Key))&&route.Flanks[0].Signals.Single().Id==signal.Id,"real design sequence retains the protecting signal and exact ownership after splitting its overlapping 0–25 and 0–30 meter guards");
        var malformed=Route();FlankProtection.Plan(malformed,Graph(),new[]{signal});malformed.Sections.RemoveAll(s=>s.Segment=="side");bool refused=false;try{RouteSignals.SplitProtection(malformed);}catch(System.IO.InvalidDataException){refused=true;}Check(refused,"guard splitting cannot silently discard an uncovered flank section and turn malformed protection into a valid route");
        var world=new World();var engine=new InterlockingEngine();engine.Request(route,world);for(int i=0;i<8;i++)engine.Tick(world);Check(engine.ForSignal("A").Permitted&&engine.FlankHoldsSignal(signal.Id)&&engine.UsesSignal(signal.Id),"established route holds its flank signal at stop and prevents moving or deleting it");var conflict=new RouteDefinition{Code="R",Entry=signal.Id,Exit="X",Shunting=true,Sections=new List<TrackSection>{S("independent")},Approach=new List<TrackSection>{S("other-approach")}};bool rejected=false;try{engine.Request(conflict,world);}catch(InvalidOperationException){rejected=true;}Check(rejected,"even a separately drawn shunt request cannot clear a signal held for flank protection");
        world.Intrusion=true;engine.Tick(world);var run=engine.ForSignal("A");Check(run.Stage==RouteStage.Fault&&!run.Permitted&&!run.Entered&&run.FaultReason.Contains("Flankenschutz")&&engine.Locked("W",true),"lateral body/occupancy intrusion drops route authority before any point change and retains locks instead of treating it as normal entry");
        signal.FacingReverse=false;route=Route();FlankProtection.Plan(route,Graph(),new[]{signal});Check(route.Flanks[0].Signals.Count==0&&route.Switches.Any(p=>p.Node=="Q"),"signal facing away from the danger point is not mistaken for a protective stop");
        route=Route();FlankProtection.Plan(route,Graph(200),new MarkerRecord[0]);Check(route.Flanks[0].MonitorOnly&&route.Flanks[0].Sections.Single().To==150,"missing protective installation is explicitly marked monitoring-only with a bounded watched approach");world=new World();engine=new InterlockingEngine();engine.Request(route,world);for(int i=0;i<8;i++)engine.Tick(world);world.Unknown=true;engine.Tick(world);Check(engine.ForSignal("A").Stage==RouteStage.Fault&&!engine.ForSignal("A").Permitted,"unknown flank monitoring cannot leave the route permissive");
        var broken=route.Clone();broken.Flanks.Clear();bool rejectedGroup=false;try{broken.Validate();}catch{rejectedGroup=true;}Check(rejectedGroup,"received route cannot claim calculated protection while silently omitting a main point group");
    }
}
